PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "last_login_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "biometric_devices" ("id" integer primary key autoincrement not null, "device_name" varchar not null, "device_ip" varchar, "device_port" integer not null default '4370', "device_model" varchar, "manufacturer" varchar not null default 'ZKSoftware', "serial_number" varchar, "mac_address" varchar, "location" varchar, "timezone" varchar not null default 'America/La_Paz', "is_active" tinyint(1) not null default '1', "auto_sync" tinyint(1) not null default '1', "sync_interval" integer not null default '60', "max_connections" integer not null default '5', "connection_timeout" integer not null default '30', "connection_type" varchar not null default 'TCP/IP', "protocol" varchar not null default 'ZKProtocol', "api_key" varchar, "api_secret" varchar, "additional_config" text, "capabilities" text, "last_sync" datetime, "last_connection_test" datetime, "connection_status" varchar not null default 'disconnected', "connection_error" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "biometric_communication_logs" ("id" integer primary key autoincrement not null, "device_id" integer not null, "command" varchar not null, "status" varchar not null, "request_data" text, "response_data" text, "error_message" text, "response_time_ms" integer, "additional_info" text, "created_at" datetime, "updated_at" datetime, foreign key("device_id") references "biometric_devices"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "biometric_device_profiles" ("id" integer primary key autoincrement not null, "manufacturer" varchar not null, "model" varchar not null, "protocol" varchar not null, "default_ports" text, "capabilities" text, "commands" text, "config_parameters" text, "description" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "work_schedules" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "is_default" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "work_schedule_days" ("id" integer primary key autoincrement not null, "work_schedule_id" integer not null, "day_of_week" integer not null, "starts_at" time, "ends_at" time, "grace_minutes" integer not null default '0', "is_working_day" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "second_starts_at" time, "second_ends_at" time, foreign key("work_schedule_id") references "work_schedules"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "attendances" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "device_id" integer, "checked_at" datetime not null, "type" varchar not null default 'in', "status" varchar not null default 'normal', "source" varchar not null default 'biometric', "raw_data" text, "created_at" datetime, "updated_at" datetime, "late_minutes" integer not null default '0', "observation" text, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("device_id") references "biometric_devices"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "offices" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar not null, "address" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "work_units" ("id" integer primary key autoincrement not null, "office_id" integer not null, "name" varchar not null, "code" varchar not null, "description" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("office_id") references "offices"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "holidays" ("id" integer primary key autoincrement not null, "name" varchar not null, "date" date not null, "scope" varchar not null default 'national', "is_recurring" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "employees" ("id" integer primary key autoincrement not null, "employee_code" varchar not null, "first_name" varchar not null, "last_name" varchar not null, "identity_document" varchar not null, "email" varchar, "phone" varchar, "position" varchar, "department" varchar, "biometric_id" integer, "hire_date" date, "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "maternal_last_name" varchar, "identity_issued_in" varchar, "has_children" tinyint(1) not null default ('0'), "address" varchar, "mobile" varchar, "birth_date" date, "marital_status" varchar, "gender" varchar, "office_id" integer, "work_unit_id" integer, "item_number" varchar, "employee_type" varchar, "budget_line" varchar, "employment_end_date" date, "job_description" text, "employment_observations" text, "memo_date" date, "memo_number" varchar, "work_schedule_id" integer, "attendance_method" varchar not null default 'biometric', "access_code" text, foreign key("work_unit_id") references work_units("id") on delete set null on update no action, foreign key("office_id") references offices("id") on delete set null on update no action, foreign key("work_schedule_id") references "work_schedules"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "biometric_templates" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "device_id" integer not null, "finger_index" integer not null, "template_data" text not null, "format" varchar not null default 'zk-template', "checksum" varchar not null, "synced_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("device_id") references "biometric_devices"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "work_schedule_assignments" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "work_schedule_id" integer not null, "starts_on" date not null, "ends_on" date, "assigned_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("employee_id") references "employees"("id") on delete cascade, foreign key("work_schedule_id") references "work_schedules"("id") on delete cascade, foreign key("assigned_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "leave_types" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime, "name" varchar not null, "code" varchar not null, "is_active" tinyint(1) not null default '1', "abbreviation" varchar, "color" varchar);
CREATE TABLE IF NOT EXISTS "leave_requests" ("id" integer primary key autoincrement not null, "employee_id" integer not null, "type" varchar not null, "starts_on" date not null, "ends_on" date not null, "reason" text, "status" varchar not null default ('pending'), "approved_by" integer, "approved_at" datetime, "created_at" datetime, "updated_at" datetime, "leave_type_id" integer, "starts_at" time, "ends_at" time, "duration_type" varchar not null default 'all_day', "half_day_period" varchar, foreign key("approved_by") references users("id") on delete set null on update no action, foreign key("employee_id") references employees("id") on delete cascade on update no action, foreign key("leave_type_id") references "leave_types"("id") on delete restrict);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "biometric_devices_device_ip_device_port_index" on "biometric_devices" ("device_ip", "device_port");
CREATE INDEX "biometric_devices_manufacturer_device_model_index" on "biometric_devices" ("manufacturer", "device_model");
CREATE INDEX "biometric_devices_connection_status_index" on "biometric_devices" ("connection_status");
CREATE UNIQUE INDEX "biometric_devices_device_name_unique" on "biometric_devices" ("device_name");
CREATE INDEX "biometric_communication_logs_device_id_created_at_index" on "biometric_communication_logs" ("device_id", "created_at");
CREATE INDEX "biometric_communication_logs_status_index" on "biometric_communication_logs" ("status");
CREATE UNIQUE INDEX "biometric_device_profiles_manufacturer_model_unique" on "biometric_device_profiles" ("manufacturer", "model");
CREATE INDEX "biometric_device_profiles_manufacturer_protocol_index" on "biometric_device_profiles" ("manufacturer", "protocol");
CREATE UNIQUE INDEX "work_schedule_days_work_schedule_id_day_of_week_unique" on "work_schedule_days" ("work_schedule_id", "day_of_week");
CREATE UNIQUE INDEX "attendances_employee_id_device_id_checked_at_unique" on "attendances" ("employee_id", "device_id", "checked_at");
CREATE INDEX "attendances_checked_at_type_index" on "attendances" ("checked_at", "type");
CREATE UNIQUE INDEX "offices_name_unique" on "offices" ("name");
CREATE UNIQUE INDEX "offices_code_unique" on "offices" ("code");
CREATE UNIQUE INDEX "work_units_office_id_name_unique" on "work_units" ("office_id", "name");
CREATE UNIQUE INDEX "work_units_office_id_code_unique" on "work_units" ("office_id", "code");
CREATE UNIQUE INDEX "holidays_date_unique" on "holidays" ("date");
CREATE UNIQUE INDEX "employees_biometric_id_unique" on "employees" ("biometric_id");
CREATE UNIQUE INDEX "employees_email_unique" on "employees" ("email");
CREATE UNIQUE INDEX "employees_employee_code_unique" on "employees" ("employee_code");
CREATE UNIQUE INDEX "employees_identity_document_unique" on "employees" ("identity_document");
CREATE INDEX "employees_is_active_department_index" on "employees" ("is_active", "department");
CREATE UNIQUE INDEX "employees_item_number_unique" on "employees" ("item_number");
CREATE UNIQUE INDEX "biometric_templates_employee_id_device_id_finger_index_unique" on "biometric_templates" ("employee_id", "device_id", "finger_index");
CREATE INDEX "biometric_templates_device_id_synced_at_index" on "biometric_templates" ("device_id", "synced_at");
CREATE INDEX "schedule_assignments_employee_dates_index" on "work_schedule_assignments" ("employee_id", "starts_on", "ends_on");
CREATE INDEX "schedule_assignments_schedule_dates_index" on "work_schedule_assignments" ("work_schedule_id", "starts_on", "ends_on");
CREATE UNIQUE INDEX "leave_types_code_unique" on "leave_types" ("code");
CREATE INDEX "leave_requests_status_starts_on_index" on "leave_requests" ("status", "starts_on");
CREATE UNIQUE INDEX "leave_types_abbreviation_unique" on "leave_types" ("abbreviation");
CREATE INDEX "employees_attendance_method_is_active_index" on "employees" ("attendance_method", "is_active");
COMMIT;
